<?php
namespace Tests\Feature;use App\Models\{Location,Organization,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
final class LocationDomainTest extends TestCase{use RefreshDatabase;private function user(Organization $o,bool $admin=false,string $role='owner'):User{return User::factory()->create(['organization_id'=>$o->id,'role'=>$role,'platform_role'=>$admin?'platform_admin':null,'status'=>'active']);}public function test_admin_crud_and_safe_staff_reference():void{$a=Organization::create(['name'=>'A','slug'=>'loc-a']);$b=Organization::create(['name'=>'B','slug'=>'loc-b']);$admin=$this->user($a,true);$staff=$this->user($a);$foreign=$this->user($b);$id=$this->actingAs($admin)->postJson('/api/admin/locations',['organization_id'=>$a->id,'name'=>' Plant   A ','description'=>'Primary'])->assertCreated()->assertJsonPath('data.name','Plant A')->json('data.id');$this->actingAs($staff)->getJson('/api/locations')->assertOk()->assertJsonPath('data.0.id',$id)->assertJsonPath('data.0.deviceCount',0);$this->actingAs($foreign)->getJson("/api/locations/$id")->assertNotFound();$this->actingAs($staff)->patchJson("/api/admin/locations/$id",['name'=>'Attack'])->assertForbidden();$this->actingAs($admin)->patchJson("/api/admin/locations/$id",['name'=>'Plant Alpha'])->assertOk();}public function test_assignment_never_grants_access_and_counts_are_scoped():void{$o=Organization::create(['name'=>'A','slug'=>'loc-device']);$admin=$this->user($o,true);$full=$this->user($o);$viewer=$this->user($o,false,'staff');$hidden=$this->user($o,false,'staff');$id=$this->actingAs($admin)->postJson('/api/admin/locations',['organization_id'=>$o->id,'name'=>'Plant'])->assertCreated()->json('data.id');$device=$this->actingAs($full)->postJson('/api/devices',['name'=>'Pump','type'=>'sensor','serialNumber'=>'L-1','protocol'=>'mqtt','location_id'=>$id])->assertCreated()->assertJsonPath('location.id',$id)->json('id');$this->assertDatabaseHas('device_access_assignments',['device_id'=>$device,'user_id'=>$full->id,'access_level'=>'full_access']);$this->assertDatabaseMissing('device_access_assignments',['device_id'=>$device,'user_id'=>$hidden->id]);$this->actingAs($viewer)->getJson('/api/locations')->assertOk()->assertJsonPath('data.0.deviceCount',0);$this->actingAs($viewer)->patchJson("/api/devices/$device",['location_id'=>null])->assertNotFound();$this->actingAs($full)->patchJson("/api/devices/$device",['location_id'=>null])->assertOk()->assertJsonPath('location',null);}public function test_cross_org_disabled_and_backfill_invariants():void{$a=Organization::create(['name'=>'A','slug'=>'loc-sec-a']);$b=Organization::create(['name'=>'B','slug'=>'loc-sec-b']);$admin=$this->user($a,true);$staff=$this->user($a);$this->actingAs($admin)->postJson('/api/admin/locations',['organization_id'=>$b->id,'name'=>'Foreign'])->assertNotFound();$foreign=Location::create(['organization_id'=>$b->id,'name'=>'Foreign','normalized_name'=>'foreign'])->id;$this->actingAs($staff)->postJson('/api/devices',['name'=>'Bad','type'=>'sensor','serialNumber'=>'L-2','protocol'=>'mqtt','location_id'=>$foreign])->assertNotFound();$local=$this->actingAs($admin)->postJson('/api/admin/locations',['organization_id'=>$a->id,'name'=>'Local'])->assertCreated()->json('data.id');$this->actingAs($admin)->postJson("/api/admin/resources/location/$local/lifecycle/disable")->assertOk();$this->actingAs($staff)->postJson('/api/devices',['name'=>'Bad2','type'=>'sensor','serialNumber'=>'L-3','protocol'=>'mqtt','location_id'=>$local])->assertConflict();$one=$a->devices()->create(['name'=>'One','external_id'=>'LB-1','status'=>'offline','type'=>'sensor','protocol'=>'mqtt','location'=>' Plant A ']);$two=$b->devices()->create(['name'=>'Two','external_id'=>'LB-2','status'=>'offline','type'=>'sensor','protocol'=>'mqtt','location'=>'plant a']);$this->artisan('locations:backfill')->assertSuccessful();$this->assertSame(2,Location::whereIn('organization_id',[$a->id,$b->id])->where('normalized_name','plant a')->count());$this->assertNotSame($one->fresh()->location_id,$two->fresh()->location_id);$this->artisan('locations:backfill')->assertSuccessful();$this->assertSame(4,Location::count());}public function test_admin_disabled_and_recent_location_integrations_are_truthful():void{$o=Organization::create(['name'=>'Recent','slug'=>'loc-recent']);$admin=$this->user($o,true);$id=$this->actingAs($admin)->postJson('/api/admin/locations',['organization_id'=>$o->id,'name'=>'Warehouse'])->assertCreated()->json('data.id');$this->actingAs($admin)->getJson('/api/admin/recently-created?resource_type=location')->assertOk()->assertJsonPath('data.0.resourceType','location')->assertJsonPath('data.0.resourceId',$id);$this->actingAs($admin)->getJson('/api/admin/recently-updated?resource_type=location')->assertOk()->assertJsonCount(0,'data');$this->actingAs($admin)->patchJson("/api/admin/locations/$id",['description'=>'Updated metadata'])->assertOk();$updatedAt=Location::findOrFail($id)->semantic_updated_at;$this->actingAs($admin)->getJson('/api/admin/recently-updated?resource_type=location')->assertOk()->assertJsonPath('data.0.resourceId',$id)->assertJsonPath('data.0.actor.id',(string)$admin->id);$this->actingAs($admin)->postJson("/api/admin/resources/location/$id/lifecycle/disable")->assertOk();$this->assertTrue(Location::findOrFail($id)->semantic_updated_at->equalTo($updatedAt));$this->actingAs($admin)->getJson('/api/admin/disabled-resources?resource_type=location')->assertOk()->assertJsonPath('data.0.resourceType','location')->assertJsonPath('data.0.accessSummary.label','devices');}}
